r"""Thermochemistry: RocketCEA wrapper plus a pre-tabulated fallback built from the same CEA runs.

Two interchangeable backends expose the same call, all inputs and outputs in SI:

* ``CEABackend``    – direct NASA-CEA through ``rocketcea`` (about 1.4 ms per call).
* ``TableBackend``  – multilinear interpolation of a grid generated by ``tools/build_thermo_tables.py``
  (vectorised, microseconds). Used automatically when ``rocketcea`` is not installed.

Quantities (chamber stagnation state, equilibrium combustion):

.. math::  c^* = \frac{P_c A_t}{\dot m}, \qquad I_{sp,vac} = \frac{F_{vac}}{\dot m\, g_0}

Sources: Sutton & Biblarz, *Rocket Propulsion Elements*, Ch. 5; Gordon & McBride, NASA RP-1311 (CEA).
"""
from __future__ import annotations

from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path

import numpy as np

from ..constants import G0

FT = 0.3048
PSI = 6894.757293168
RANKINE = 5.0 / 9.0
DATA = Path(__file__).resolve().parent / "data" / "cea_tables.npz"


@dataclass(frozen=True)
class Pair:
    """A propellant pair with the O/F range worth plotting."""

    key: str
    label: str
    ox: str
    fuel: str
    mr_lo: float
    mr_hi: float


PAIRS: dict[str, Pair] = {p.key: p for p in [
    Pair("LOX/RP-1", "LOX / RP-1", "LOX", "RP-1", 1.4, 3.6),
    Pair("LOX/LH2", "LOX / LH₂", "LOX", "H2", 2.0, 10.0),
    Pair("LOX/CH4", "LOX / CH₄", "LOX", "CH4", 1.8, 4.5),
    Pair("LOX/Ethanol", "LOX / ethanol", "LOX", "Ethanol", 0.8, 2.2),
    Pair("N2O4/MMH", "N₂O₄ / MMH", "N2O4", "MMH", 1.0, 2.8),
    Pair("LOX/HTPB", "LOX / HTPB", "LOX", "HTPB", 1.3, 4.0),
    Pair("GOX/HTPB", "GOX / HTPB", "GOX", "HTPB", 1.3, 6.0),
    Pair("N2O/HTPB", "N₂O / HTPB", "N2O", "HTPB", 3.5, 12.0),
]}

PC_RANGE = (0.5e6, 20e6)          # (Pa) table coverage
EPS_RANGE = (1.5, 100.0)


@dataclass
class Chamber:
    """Chamber / throat state for one (pair, O/F, P_c); arrays broadcast like the inputs."""

    cstar: np.ndarray       # (m·s⁻¹)
    Tc: np.ndarray          # (K)
    gamma: np.ndarray       # throat isentropic exponent (–)
    Mw: np.ndarray          # throat mean molar mass (kg·mol⁻¹)


class CEABackend:
    """Direct RocketCEA calls (units converted at the boundary)."""

    name = "CEA (direct)"

    def __init__(self) -> None:
        from rocketcea.cea_obj import CEA_Obj  # noqa: F401  (import test)
        self._cls = CEA_Obj

    @lru_cache(maxsize=32)
    def _obj(self, key: str):
        p = PAIRS[key]
        return self._cls(oxName=p.ox, fuelName=p.fuel)

    def _one(self, key: str, mr: float, pc: float, eps: float, frozen: bool):
        o = self._obj(key)
        pc_psia = pc / PSI
        iv, cs, tc = o.get_IvacCstrTc(Pc=pc_psia, MR=mr, eps=eps, frozen=1 if frozen else 0)
        if not (iv > 0 and cs > 0):      # CEA silently returns zeros when frozen flow fails (e.g. fuel-rich HTPB)
            raise RuntimeError(f"CEA found no solution: {key} O/F={mr:.3f} Pc={pc / 1e6:.2f} MPa eps={eps:.2f} "
                               f"{'frozen' if frozen else 'equilibrium'}")
        mw, g = o.get_Throat_MolWt_gamma(Pc=pc_psia, MR=mr, eps=eps)
        return float(iv), float(cs) * FT, float(tc) * RANKINE, float(g), float(mw) * 1e-3

    def evaluate(self, key: str, mr, pc, eps, frozen: bool = False) -> dict[str, np.ndarray]:
        mr, pc, eps = np.broadcast_arrays(*(np.asarray(v, float) for v in (mr, pc, eps)))
        out = {k: np.empty(mr.shape) for k in ("ivac", "cstar", "Tc", "gamma", "Mw")}
        for idx in np.ndindex(mr.shape):
            iv, cs, tc, g, mw = self._one(key, float(mr[idx]), float(pc[idx]), float(eps[idx]), frozen)
            out["ivac"][idx], out["cstar"][idx], out["Tc"][idx], out["gamma"][idx], out["Mw"][idx] = iv, cs, tc, g, mw
        return out


class TableBackend:
    """Multilinear interpolation on the shipped CEA grids (axes: O/F, ln P_c, ln eps)."""

    name = "CEA tables"

    def __init__(self, path: Path = DATA) -> None:
        if not path.exists():
            raise FileNotFoundError(f"thermo table {path} missing (run tools/build_thermo_tables.py)")
        z = np.load(path, allow_pickle=False)
        self._z = {k: z[k] for k in z.files}

    def has(self, key: str) -> bool:
        return f"{key}__mr" in self._z

    @staticmethod
    def _interp(axes, values, pts):
        """Multilinear interpolation of ``values`` (grid over ``axes``) at ``pts`` (list of arrays)."""
        idx, wts = [], []
        for ax, x in zip(axes, pts):
            x = np.clip(x, ax[0], ax[-1])
            i = np.clip(np.searchsorted(ax, x) - 1, 0, len(ax) - 2)
            idx.append(i)
            wts.append((x - ax[i]) / (ax[i + 1] - ax[i]))
        out = 0.0
        for corner in range(2 ** len(axes)):
            w, ii = 1.0, []
            for d in range(len(axes)):
                bit = (corner >> d) & 1
                w = w * (wts[d] if bit else 1.0 - wts[d])
                ii.append(idx[d] + bit)
            out = out + w * values[tuple(ii)]
        return out

    def evaluate(self, key: str, mr, pc, eps, frozen: bool = False) -> dict[str, np.ndarray]:
        z = self._z
        mr, pc, eps = np.broadcast_arrays(*(np.asarray(v, float) for v in (mr, pc, eps)))
        a_mr, a_p, a_e = z[f"{key}__mr"], z[f"{key}__lnpc"], z[f"{key}__lneps"]
        lp, le = np.log(pc), np.log(eps)
        out = {n: self._interp((a_mr, a_p), z[f"{key}__{src}"], (mr, lp))
               for n, src in (("cstar", "cstar_fr" if frozen else "cstar"), ("Tc", "Tc"), ("gamma", "gamma"),
                              ("Mw", "Mw"))}
        out["ivac"] = self._interp((a_mr, a_p, a_e), z[f"{key}__ivac_{'fr' if frozen else 'eq'}"], (mr, lp, le))
        return out


def cea_available() -> bool:
    try:
        import rocketcea.cea_obj  # noqa: F401
        return True
    except Exception:
        return False


def tables_available() -> bool:
    return DATA.exists()


@lru_cache(maxsize=4)
def get_backend(source: str = "auto"):
    """``'tables'`` | ``'cea'`` | ``'auto'`` (tables if shipped, else CEA). Raises if neither exists."""
    if source == "cea" or (source == "auto" and not tables_available()):
        if not cea_available():
            raise RuntimeError("rocketcea is not installed and no thermo tables are shipped")
        return CEABackend()
    return TableBackend()


class Thermo:
    """Facade used by physics and UI: SI in, SI out."""

    def __init__(self, pair: str, source: str = "auto", frozen: bool = False) -> None:
        self.pair = PAIRS[pair]
        self.frozen = frozen
        self.backend = get_backend(source)

    @property
    def source(self) -> str:
        return self.backend.name

    def chamber(self, mr, pc) -> Chamber:
        """Chamber state; independent of area ratio (a reference eps of 4 is used for the call)."""
        r = self.backend.evaluate(self.pair.key, mr, pc, 4.0, self.frozen)
        return Chamber(r["cstar"], r["Tc"], r["gamma"], r["Mw"])

    def isp_vac(self, mr, pc, eps) -> np.ndarray:
        """Vacuum specific impulse (s) for a nozzle of area ratio ``eps``."""
        return self.backend.evaluate(self.pair.key, mr, pc, eps, self.frozen)["ivac"]

    def isp_sl(self, mr, pc, eps, pa: float = 101325.0) -> np.ndarray:
        r"""Specific impulse at ambient pressure ``pa``: :math:`I_{sp}=I_{vac}-\frac{P_a\varepsilon c^*}{P_c g_0}`."""
        r = self.backend.evaluate(self.pair.key, mr, pc, eps, self.frozen)
        return r["ivac"] - pa * np.asarray(eps) * r["cstar"] / (np.asarray(pc) * G0)

    def cf_vac(self, mr, pc, eps) -> np.ndarray:
        r"""Vacuum thrust coefficient :math:`C_{F,vac}=\frac{I_{vac} g_0}{c^*}` (CEA-consistent, includes losses of
        equilibrium/frozen chemistry)."""
        r = self.backend.evaluate(self.pair.key, mr, pc, eps, self.frozen)
        return r["ivac"] * G0 / r["cstar"]

    def point(self, mr: float, pc: float, eps: float, pa: float = 101325.0) -> dict[str, float]:
        """All headline numbers at one operating point (one backend call)."""
        r = self.backend.evaluate(self.pair.key, mr, pc, eps, self.frozen)
        iv, cs = float(r["ivac"]), float(r["cstar"])
        return dict(cstar=cs, Tc=float(r["Tc"]), gamma=float(r["gamma"]), Mw=float(r["Mw"]), isp_vac=iv,
                    isp_sl=iv - pa * eps * cs / (pc * G0), cf_vac=iv * G0 / cs)


class ChamberLUT:
    """Fast scalar chamber lookup ``(c*, T_c, gamma, M_w)`` at (O/F, P_c) from the shipped tables.

    Meant for ODE right-hand sides called thousands of times (about 15 µs per call); inputs outside the table are
    clamped to its edge. Bilinear in (O/F, ln P_c)."""

    def __init__(self, pair: str, frozen: bool = False) -> None:
        z = TableBackend()._z
        self.mr, self.lnp = z[f"{pair}__mr"], z[f"{pair}__lnpc"]
        self._f = [z[f"{pair}__{'cstar_fr' if frozen else 'cstar'}"], z[f"{pair}__Tc"], z[f"{pair}__gamma"],
                   z[f"{pair}__Mw"]]

    def __call__(self, mr: float, pc: float) -> tuple[float, float, float, float]:
        lp = min(max(np.log(max(pc, 1.0)), self.lnp[0]), self.lnp[-1])
        j = min(int(np.searchsorted(self.lnp, lp)) - 1, len(self.lnp) - 2)
        j = max(j, 0)
        w = (lp - self.lnp[j]) / (self.lnp[j + 1] - self.lnp[j])
        return tuple(float(np.interp(mr, self.mr, (1.0 - w) * a[:, j] + w * a[:, j + 1])) for a in self._f)


@lru_cache(maxsize=8)
def chamber_lut(pair: str, frozen: bool = False) -> ChamberLUT:
    return ChamberLUT(pair, frozen)
